#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"

void app_main(void) {
    ESP_LOGI("init", "Starting long initialization...");

    for (int i = 0; i < 1000000; i++) {
        // Very long initialization without yielding
        volatile int x = i * i;
    }

    ESP_LOGI("init", "Initialization complete");

    while (1) {
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}
